import matplotlib.pyplot as plt

def task_func(data: np.ndarray) -> plt.Axes:
    arr = np.asarray(data)

    if not np.issubdtype(arr.dtype, np.number):
        raise TypeError("Input array must contain numeric values.")

    if np.issubdtype(arr.dtype, np.complexfloating):
        raise TypeError("Input array must contain real numeric values.")

    arr = np.ravel(arr)

    if np.isnan(arr).any():
        raise ValueError("Input array must not contain NaN values.")

    if (arr < 0).any():
        raise ValueError("Input array must not contain negative values.")

    sorted_data = np.sort(arr.astype(float, copy=False))
    n = sorted_data.size

    if n == 0:
        cumulative_probability = np.array([], dtype=float)
    else:
        total = sorted_data.sum()
        if total == 0:
            cumulative_probability = np.zeros(n, dtype=float)
        else:
            cumulative_probability = np.cumsum(sorted_data) / total

    fig, ax = plt.subplots()
    ax.plot(np.arange(n), cumulative_probability, marker="o", linestyle="-")
    ax.set_title("Cumulative Probability Plot")
    ax.set_xlabel("Index")
    ax.set_ylabel("Cumulative Probability")

    return ax

import sqlite3
import pandas as pd
import os
import re


def task_func(db_file, table_name, column_name, pattern='\d+[xX]'):
    """
    Load all rows from an SQLite table, find regex matches in the specified column,
    and return the matches as a pandas DataFrame.
    """
    if not os.path.exists(db_file):
        raise ValueError(f"Database file does not exist: {db_file}")

    def _quote_identifier(identifier):
        return '"' + str(identifier).replace('"', '""') + '"'

    regex = re.compile(pattern)

    with sqlite3.connect(db_file) as conn:
        query = f"SELECT * FROM {_quote_identifier(table_name)}"
        df = pd.read_sql_query(query, conn)

    if column_name not in df.columns:
        raise KeyError(f"Column not found: {column_name}")

    def _extract_matches(value):
        if value is None:
            return []
        try:
            if pd.isna(value):
                return []
        except Exception:
            pass

        if isinstance(value, (list, tuple, set)):
            text = " ".join(map(str, value))
        else:
            text = str(value)

        return regex.findall(text)

    matches = df[column_name].apply(_extract_matches)

    if not matches.astype(bool).any():
        return pd.DataFrame(columns=list(df.columns) + ["matches"])

    result = df.loc[matches.astype(bool)].copy()
    result["matches"] = matches[matches.astype(bool)].values
    result = result.explode("matches", ignore_index=True)

    return result

