# Constants
DATE_FORMAT = '%Y-%m-%d %H:%M:%S'


def task_func(result):
    """
    Compute summary statistics for all 'from_user' values found in `result`.

    Returns
    -------
    pd.Series
        Index contains: mean, median, min, max, std, current_time

    Raises
    ------
    ValueError
        If any extracted 'from_user' value is not numeric.
    """
    import numbers

    def is_numeric(value):
        # Treat booleans as non-numeric for this task.
        return isinstance(value, numbers.Real) and not isinstance(value, bool)

    def extract_from_user_values(obj):
        values = []

        if obj is None:
            return values

        # Pandas DataFrame
        if isinstance(obj, pd.DataFrame):
            if "from_user" in obj.columns:
                values.extend(obj["from_user"].tolist())
            return values

        # Pandas Series
        if isinstance(obj, pd.Series):
            if obj.name == "from_user":
                values.extend(obj.tolist())
            else:
                # If the Series contains dict-like elements, inspect them.
                for item in obj.tolist():
                    if isinstance(item, dict) and "from_user" in item:
                        values.append(item["from_user"])
                    elif hasattr(item, "get"):
                        try:
                            values.append(item.get("from_user"))
                        except Exception:
                            pass
            return values

        # Dictionary input
        if isinstance(obj, dict):
            if "from_user" in obj:
                val = obj["from_user"]
                if isinstance(val, (list, tuple, np.ndarray, pd.Series)):
                    values.extend(list(val))
                else:
                    values.append(val)
            return values

        # General iterable of records
        if isinstance(obj, (list, tuple, np.ndarray)):
            for item in obj:
                if isinstance(item, dict):
                    if "from_user" in item:
                        values.append(item["from_user"])
                elif isinstance(item, pd.Series):
                    if "from_user" in item.index:
                        values.append(item["from_user"])
                elif hasattr(item, "get"):
                    try:
                        values.append(item.get("from_user"))
                    except Exception:
                        pass
            return values

        # Single record-like object
        if hasattr(obj, "get"):
            try:
                if obj.get("from_user") is not None:
                    values.append(obj.get("from_user"))
            except Exception:
                pass

        return values

    raw_values = extract_from_user_values(result)

    if len(raw_values) == 0:
        stats = {
            "mean": np.nan,
            "median": np.nan,
            "min": np.nan,
            "max": np.nan,
            "std": np.nan,
        }
    else:
        if not all(is_numeric(v) for v in raw_values):
            raise ValueError('If the "from_user" values are not numeric.')

        arr = np.asarray(raw_values, dtype=float)

        stats = {
            "mean": np.mean(arr),
            "median": np.median(arr),
            "min": np.min(arr),
            "max": np.max(arr),
            "std": np.std(arr),
        }

    stats["current_time"] = datetime.now().strftime(DATE_FORMAT)

    return pd.Series(stats)

import os
import glob
import uuid

def task_func(directory_path):
    def reverse_period_words(name):
        parts = name.split(".")
        if len(parts) == 1:
            return name

        prefix = 0
        while prefix < len(parts) and parts[prefix] == "":
            prefix += 1

        suffix = 0
        while suffix < len(parts) - prefix and parts[len(parts) - 1 - suffix] == "":
            suffix += 1

        middle = parts[prefix:len(parts) - suffix]
        if len(middle) <= 1:
            return name

        new_parts = [""] * prefix + list(reversed(middle)) + [""] * suffix
        return ".".join(new_parts)

    if not os.path.isdir(directory_path):
        return []

    paths = []
    for pattern in (os.path.join(directory_path, "*"), os.path.join(directory_path, ".*")):
        paths.extend(glob.glob(pattern))
    paths = [p for p in sorted(set(paths)) if os.path.isfile(p)]

    new_filenames = []
    temp_moves = []

    for idx, path in enumerate(paths):
        base = os.path.basename(path)
        new_base = reverse_period_words(base)
        new_filenames.append(new_base)

        if new_base != base:
            temp_name = f".__tmp_reverse_words__{os.getpid()}_{idx}_{uuid.uuid4().hex}__{base}"
            temp_path = os.path.join(directory_path, temp_name)
            os.rename(path, temp_path)
            temp_moves.append((temp_path, os.path.join(directory_path, new_base)))

    for temp_path, final_path in temp_moves:
        os.rename(temp_path, final_path)

    return new_filenames

