from nltk.stem import PorterStemmer
from collections import Counter
STEMMER = PorterStemmer()

def task_func(content):
    if content is None:
        return {}

    text = str(content)
    words = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text)
    if len(words) <= 1:
        return {}

    stems = [STEMMER.stem(word.lower()) for word in words[:-1]]
    return dict(Counter(stems))

import pandas as pd
import numpy as np
from scipy.stats import chi2_contingency


def task_func(data, col1, col2):
    if data.empty:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    if col1 not in data.columns or col2 not in data.columns:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    s1 = data[col1]
    s2 = data[col2]

    def _is_categorical(series):
        dtype = series.dtype
        return (
            pd.api.types.is_categorical_dtype(dtype)
            or pd.api.types.is_object_dtype(dtype)
            or pd.api.types.is_string_dtype(dtype)
            or pd.api.types.is_bool_dtype(dtype)
        )

    if not _is_categorical(s1) or not _is_categorical(s2):
        raise TypeError("If one or both of the columns contain non-categorical data.")

    df = data[[col1, col2]].dropna()
    if df.empty:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    s1 = df[col1]
    s2 = df[col2]

    if s1.nunique(dropna=True) < 2 or s2.nunique(dropna=True) < 2:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    if (s1.value_counts(dropna=True) < 5).any() or (s2.value_counts(dropna=True) < 5).any():
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    contingency_table = pd.crosstab(df[col1], df[col2])
    _, p_value, _, _ = chi2_contingency(contingency_table)

    return float(p_value)

import os
import re


def task_func(pattern: str, replacement: str, directory: str) -> bool:
    try:
        if not os.path.isdir(directory):
            return False
        regex = re.compile(pattern)
    except Exception:
        return False

    try:
        planned = []
        with os.scandir(directory) as it:
            for entry in it:
                if entry.is_dir(follow_symlinks=False):
                    continue
                name = entry.name
                new_name = regex.sub(replacement, name)
                if new_name != name:
                    if not new_name or new_name in {".", ".."}:
                        return False
                    if os.path.basename(new_name) != new_name:
                        return False
                    planned.append((name, new_name))
    except Exception:
        return False

    if not planned:
        return True

    final_to_source = {}
    for src, dst in planned:
        other = final_to_source.get(dst)
        if other is not None and other != src:
            return False
        final_to_source[dst] = src

    src_names = {src for src, _ in planned}
    final_names = {dst for _, dst in planned}

    try:
        existing_names = set(os.listdir(directory))
    except Exception:
        return False

    for src, dst in planned:
        if dst in existing_names and dst not in src_names:
            return False

    used_names = set(existing_names)
    used_names.update(final_names)

    rename_plan = []
    for idx, (src, dst) in enumerate(planned):
        prefix = f".__rename_tmp__{idx}__"
        counter = 0
        while True:
            temp_name = f"{prefix}{counter}__{src}"
            if temp_name not in used_names:
                used_names.add(temp_name)
                break
            counter += 1
        rename_plan.append((src, dst, temp_name))

    moved_to_temp = []
    moved_to_final = []

    try:
        for src, dst, temp_name in rename_plan:
            src_path = os.path.join(directory, src)
            temp_path = os.path.join(directory, temp_name)
            os.rename(src_path, temp_path)
            moved_to_temp.append((src_path, temp_path))

        for src, dst, temp_name in rename_plan:
            temp_path = os.path.join(directory, temp_name)
            final_path = os.path.join(directory, dst)
            os.rename(temp_path, final_path)
            moved_to_final.append((temp_path, final_path))

        return True
    except Exception:
        for temp_path, final_path in reversed(moved_to_final):
            try:
                os.rename(final_path, temp_path)
            except Exception:
                pass

        for src_path, temp_path in reversed(moved_to_temp):
            try:
                os.rename(temp_path, src_path)
            except Exception:
                pass

        return False

